{
  "case_id": "xsu_sg_007_work_stopped_due_to_impairment",
  "criteria": {
    "c01_overall_legal_correctness": {"label": "met", "reason": "Konklusionen 'nej, ikke i sig selv ret' stemmer med rubrikken og vejledningen 3.4.1.3. Udsagnene om vurdering af andre typer arbejde, skånehensyn eller mindre omfang og gener med skånebehov svarer til kilden. Der er ingen væsentlig juridisk fejl."},
    "c02_required_elements_complete": {"label": "not_met", "reason": "Svaret nævner ikke udtrykkeligt, at arbejdets karakter sammenholdes med funktionsnedsættelsen. Det angiver heller ikke, at vurderingen bygger på sagens øvrige oplysninger. Skånehensyn og mindre omfang er med, men to af tre kritiske elementer mangler eller er kun antydet."},
    "c03_direct_relevance": {"label": "met", "reason": "Svaret besvarer begge dele af spørgsmålet: om arbejdsophør i sig selv giver ret (nej), og hvad Udbetaling Danmark vurderer."},
    "c04_source_traceability": {"label": "not_met", "reason": "Svaret angiver ingen kilde, hverken bestemmelse eller vejledningsafsnit."},
    "c05_source_validity": {"label": "not_assessable", "reason": "Ingen kilde er angivet i svaret, så gyldigheden kan ikke vurderes."},
    "c06_claim_source_support": {"label": "not_assessable", "reason": "Ingen kilde er angivet i svaret, så støtten fra kilden kan ikke vurderes."},
    "c07_no_unsupported_legal_additions": {"label": "met", "reason": "Svaret tilføjer ingen regler, betingelser eller myndigheder ud over det, vejledningspassagen og rubrikken understøtter."},
    "c08_qualifications_and_exceptions": {"label": "not_met", "reason": "Svaret siger, at arbejdsophør ikke i sig selv giver ret. Det fremgår ikke, at ansøgerens oplysning om arbejdsophør er udgangspunkt for en nærmere vurdering ('efter det oplyste'). Det fremgår heller ikke, at ikke-fysisk belastende arbejde kun er et eksempel. Eksemplet er udeladt, hvilket i sig selv er acceptabelt."},
    "c09_reasoning_coherence": {"label": "met", "reason": "Det er sammenhængende, at arbejdsophør ikke i sig selv er afgørende, og at der foretages en bredere vurdering af arbejdsevne og skånebehov."},
    "c10_legal_modality_precision": {"label": "met", "reason": "Svaret bruger 'vurderer' og 'evt.' i overensstemmelse med kilden. Det gør ikke vurderingen til en automatisk regel."}
  },
  "xhaile_coverage": {
    "A22": {"label": "partial", "reason": "Svaret dækker vurderingen af andre typer arbejde og gener med skånebehov. Det fremgår ikke tydeligt, at arbejdets karakter ses i forhold til funktionsnedsættelsen, og at udgangspunktet er, at arbejdet er ophørt på grund af funktionsnedsættelsen efter det oplyste."},
    "A23": {"label": "yes", "reason": "Svaret angiver, at Udbetaling Danmark vurderer, om ansøgeren kan varetage andre typer arbejde, evt. med skånehensyn eller i mindre omfang."}
  },
  "overall_notes": "Svaret er juridisk korrekt i sin konklusion og i hovedtrækkene, men det er kort og angiver ingen kilde. Det udelader to kritiske elementer: sammenholdelsen af arbejdets karakter med funktionsnedsættelsen og brugen af sagens øvrige oplysninger. Det udelader også kvalifikationen om, at arbejdsophøret er et oplyst udgangspunkt for en nærmere vurdering."
}

